WITH recent_suppliers AS (SELECT * FROM suppliers WHERE country IN ('DE', 'TH')), rating_bucket_summary AS (SELECT CASE WHEN rating >= 3.9 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, country, ROUND(AVG(rating), 2) AS avg_rating FROM recent_suppliers GROUP BY CASE WHEN rating >= 3.9 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END, country) SELECT * FROM rating_bucket_summary ORDER BY country;
